using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
namespace KingswayWorkshop;
public static class RevisionTests {
 public static object Run(Store store){var checks=new List<object>();void Check(bool ok,string name){checks.Add(new{name,passed=ok});Json.Save(Path.Combine(store.Root,"Evidence","schema3-backend.json"),new{passed=ok,checks});if(!ok)throw new Exception("FAIL: "+name);}
  string root=Path.Combine(store.Root,"Builds","schema3-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"Catalog"));File.Copy(Path.Combine(store.Root,"Catalog","catalog.json"),Path.Combine(root,"Catalog","catalog.json"));var sandbox=new Store(root,store.GameRoot);
  var actual=Json.Read<Manifest>(Path.Combine(store.Root,"Tests","Migration","authored-schema2.json"));var source=store.Project(actual.Id);string recovery=Path.Combine(store.Root,"Recovery","schema3-projects","Projects");if(Directory.Exists(recovery))source=Directory.GetDirectories(recovery,actual.Id+"-*").FirstOrDefault(d=>File.Exists(Path.Combine(d,"mod.json"))&&Json.Read<Manifest>(Path.Combine(d,"mod.json")).SchemaVersion==2)??source;string target=sandbox.Project(actual.Id);Directory.CreateDirectory(target);Revision.CopyFiles(source,target);Json.Save(Path.Combine(target,"mod.json"),actual);actual.Directory=target;
  int Count(List<ActionNode> nodes)=>nodes.Sum(n=>1+Count(n.Children)+Count(n.Else));
  var before=Revision.Clone(actual);string original=Game.Hash(Path.Combine(target,"mod.json"));var converted=Revision.Load(sandbox,Path.Combine(target,"mod.json"));
  Check(converted.SchemaVersion==3&&Validation.Check(new(){converted},store.Catalog).Count==0,"Actual authored project converts and validates with complete media");
  var usedAudio=converted.Audio.Values.SelectMany(a=>new[]{a.File,a.Original}).ToHashSet(StringComparer.OrdinalIgnoreCase);Check(before.Audio.Values.SelectMany(a=>new[]{a.File,a.Original}).Where(p=>p!=""&&!usedAudio.Contains(p)).All(p=>!File.Exists(Path.Combine(target,p)))&&Directory.GetFiles(Path.Combine(root,"Recovery","schema3-retired-audio"),"*",SearchOption.AllDirectories).Length>0,"Converted audio retires old opaque filenames to recovery after the manifest commits");
  Check(before.Enemies.Zip(converted.Enemies).All(p=>Count(p.First.Actions)==Count(p.Second.Actions)&&Count(p.First.WhenAttacked)==Count(p.Second.WhenAttacked)&&Count(p.First.Periodic)==Count(p.Second.Periodic)),"Actual project retains every action node in every section");
  bool Same(List<ActionNode> old,List<ActionNode> modern){if(old.Count!=modern.Count)return false;for(int i=0;i<old.Count;i++){var a=old[i];var b=modern[i];if(a.WaitMin!=b.WaitMin||a.WaitMax!=b.WaitMax||a.Repeat!=b.Repeat||a.Interval!=b.Interval||a.Chance!=b.Chance||a.Cooldown!=b.Cooldown||a.Target!=b.Target||a.PositiveDamageOnly!=b.PositiveDamageOnly||a.DespiteBlocking!=b.DespiteBlocking||!Same(a.Children,b.Children)||!Same(a.Else,b.Else))return false;}return true;}
  Check(before.Enemies.Zip(converted.Enemies).All(p=>Same(p.First.Actions,p.Second.Actions)&&Same(p.First.Periodic,p.Second.Periodic)&&Same(p.First.WhenAttacked,p.Second.WhenAttacked)),"Migration preserves order, timing, targets, gates and nested branches");
  Check(Directory.GetFiles(Path.Combine(root,"Recovery","schema3-projects"),"mod.json",SearchOption.AllDirectories).Any(p=>Game.Hash(p)==original),"Original manifest bytes are recoverable");
  string hash=Game.Hash(Path.Combine(target,"mod.json"));int files=Directory.GetFiles(target,"*",SearchOption.AllDirectories).Length;Revision.Load(sandbox,Path.Combine(target,"mod.json"));Check(hash==Game.Hash(Path.Combine(target,"mod.json"))&&files==Directory.GetFiles(target,"*",SearchOption.AllDirectories).Length,"Second conversion is a no-op without additional files");
  var focused=new Manifest{SchemaVersion=2,Id="focused",Enemies=new(){new(){Id="head",Components=new(){new(){Enemy="part",Role="friend"}},Movement=new(){Shape="arc",StartMode="randomX",Bend=-.4,Points=new(){new(){X=.2,Y=.4},new(){X=.7,Y=.8}}},Actions=new(){new(){Kind="alternate",Repeat=2,WaitMin=.2,WaitMax=.4,Children=new(){new(){Kind="chance",Chance=37,Else=new(){new(){Kind="lifesteal",Amount=27}},Children=new(){new(){Kind="window",Operation="move",WindowBasis="relative",WindowPlacement="randomY",WindowMinY=-.8,WindowMaxY=.2,WindowDuration=.9},new(){Kind="manaDrain",Amount=3,HealPerMana=1.5,PositiveDamageOnly=true}}}},Else=new(){new(){Kind="status",StatusOperation="reduce",Amount=2,Family="burn"},new(){Kind="wait",WaitMin=.25,WaitMax=.25}}}},Periodic=new(){new(){Kind="cooldown",Cooldown=2,Children=new(){new(){Kind="spawn",Enemy="part"}}}}},new(){Id="part"}},StatusVariants=new(){new(){Id="ember",Family="burn",Message="Ember"}},Overrides=new(){new(){Slot="obj_Brogt",Enemy="head"}}};
  var focusedOriginal=Revision.Clone(focused);Revision.Upgrade(focused);var lower=Revision.Runtime(focused);var oldMove=focusedOriginal.Enemies[0].Actions[0].Children[0].Children[0];var move=lower.Enemies[0].Actions[0].Children[0].Children[0];var drain=lower.Enemies[0].Actions[0].Children[0].Children[1];
  Check(Same(focusedOriginal.Enemies[0].Actions,focused.Enemies[0].Actions)&&focused.Enemies[0].Components[0].Role=="separate"&&focused.Overrides[0].Enemy=="head","Focused nested graph, relationship and boss overrides remain independent");
  Check(move.Kind=="window"&&move.Operation=="move"&&move.WindowBasis==oldMove.WindowBasis&&move.WindowPlacement==oldMove.WindowPlacement&&move.WindowMinY==oldMove.WindowMinY&&move.WindowDuration==oldMove.WindowDuration,"Converted named move lowers to the exact original placement operation");
  Check(drain.Kind=="resourceChange"&&drain.Mode=="transfer"&&drain.Resource=="mana"&&drain.DestinationResource=="health"&&drain.Multiplier==1.5,"Old mana drain preserves the exact health-per-mana transfer");
  Check(focused.Enemies[0].Movement.Points.All(p=>p.Shape=="arc"&&p.Bend==-.4)&&focused.Enemies[0].Movement.LegacySpawnOffset&&focused.StatusVariants[0].Popup=="custom","Legacy arcs, random placement and status popup behavior convert explicitly");
  string bad=sandbox.Project("invalid_conversion");Directory.CreateDirectory(bad);var invalid=new Manifest{SchemaVersion=2,Id="invalid_conversion",Enemies=new(){new(){Image="missing"}}};Json.Save(Path.Combine(bad,"mod.json"),invalid);string badHash=Game.Hash(Path.Combine(bad,"mod.json"));bool rejected=false;try{Revision.Load(sandbox,Path.Combine(bad,"mod.json"));}catch{rejected=true;}Check(rejected&&Game.Hash(Path.Combine(bad,"mod.json"))==badHash,"Failed conversion leaves the original manifest unchanged");
  // Keep this rejected fixture out of subsequent project enumeration.
  File.Move(Path.Combine(bad,"mod.json"),Path.Combine(bad,"rejected-manifest.json"));
  var copy=sandbox.Duplicate(converted.Id);Check(copy.Id!=converted.Id&&copy.Name==converted.Name+" Copy"&&sandbox.Enabled().Count==0&&!Directory.Exists(sandbox.Project(copy.Id,"Mods")),"Project duplication publishes a complete independent source without managed state");
  Check(copy.Audio.All(a=>Game.Hash(Validation.Within(copy.Directory,a.Value.File))==Game.Hash(Validation.Within(converted.Directory,converted.Audio[a.Key].File))),"Duplicate project retains readable audio and bytes");
  copy.Enemies[0].Name="Independent";sandbox.Save(copy);Check(sandbox.List().Single(x=>x.Id==converted.Id).Enemies[0].Name==converted.Enemies[0].Name,"Changing a duplicated enemy leaves the original definition unchanged");
  var wav=File.ReadAllBytes(Path.Combine(store.Root,"Tests","Fixture","probe.wav"));var upload=AssetUploads.Audio(sandbox,copy.Id,"music","music",".wav",wav,"Boss Theme.wav");var uploaded=sandbox.List().Single(x=>x.Id==copy.Id);var meta=uploaded.Audio[upload.Name];Check(upload.Name=="boss_theme"&&meta.OriginalFilename=="Boss Theme.wav"&&meta.Original=="audio/Boss_Theme.wav"&&meta.File=="audio/Boss_Theme_toOgg.ogg","WAV music retains original filename and readable original/converted basenames");var upload2=AssetUploads.Audio(sandbox,copy.Id,"sound","sound",".wav",wav,"Boss Theme.wav");Check(upload2.Name=="boss_theme_2"&&upload2.Audio.File=="audio/Boss_Theme_2.wav","Audio collisions receive deterministic numeric suffixes without overwrite");
  string deployed=Path.Combine(root,"deployment");Directory.CreateDirectory(deployed);string originalAudio=Validation.Within(uploaded.Directory,meta.File);string basename=Path.GetFileName(originalAudio);File.WriteAllBytes(Path.Combine(deployed,basename),new byte[]{1,2,3});string unique=AudioAssets.DeploymentFilename(deployed,originalAudio);Check(unique==Path.GetFileNameWithoutExtension(basename)+"_2.ogg"&&File.ReadAllBytes(Path.Combine(deployed,basename)).SequenceEqual(new byte[]{1,2,3}),"Deployment collisions preserve existing content and use readable numeric suffixes");File.Copy(originalAudio,Path.Combine(deployed,unique));Check(AudioAssets.DeploymentFilename(deployed,originalAudio)==unique,"Repeated audio deployment reuses the same content and filename");
  sandbox.Stage(copy.Id);string enabled=File.ReadAllText(Path.Combine(root,"enabled.json"));string manifest=Game.Hash(Path.Combine(copy.Directory,"mod.json"));int calls=0;bool failed=false;try{sandbox.Remove(copy.Id,copy.Name,path=>{if(++calls==1)Directory.Move(path,path+".recycled-test");else throw new IOException("Injected recycling failure");});}catch{failed=true;}Check(failed&&Game.Hash(Path.Combine(copy.Directory,"mod.json"))==manifest&&Directory.Exists(sandbox.Project(copy.Id,"Mods"))&&File.ReadAllText(Path.Combine(root,"enabled.json"))==enabled,"Removal failure restores source, managed state and exact enabled bytes");
  var untouched=Game.Hash(Path.Combine(converted.Directory,"mod.json"));sandbox.Remove(copy.Id,copy.Name,path=>Directory.Move(path,path+".recycled-success"));Check(!Directory.Exists(copy.Directory)&&!Directory.Exists(sandbox.Project(copy.Id,"Mods"))&&!sandbox.Enabled().ContainsKey(copy.Id)&&Game.Hash(Path.Combine(converted.Directory,"mod.json"))==untouched,"Removal targets only the chosen project and clears its managed state");
  var bytes=sandbox.Export(converted.Id);string roundtrip=Path.Combine(root,"roundtrip");Directory.CreateDirectory(Path.Combine(roundtrip,"Catalog"));File.Copy(Path.Combine(root,"Catalog","catalog.json"),Path.Combine(roundtrip,"Catalog","catalog.json"));var reopen=new Store(roundtrip,store.GameRoot);reopen.Import(bytes);Check(reopen.List()[0].SchemaVersion==3&&reopen.ValidateProject(converted.Id).Count==0,"Converted project exports, imports and reopens with resolved references");
  var negative=Revision.Clone(converted);negative.Directory=converted.Directory;negative.Enemies[0].Actions=new(){new(){Kind="damage",Mode="true",Amount=-1}};Check(Validation.Check(new(){negative},store.Catalog).Any(x=>x.Field.EndsWith("amount")),"Negative authored damage is rejected");
  Check(!AudioAssets.NeedsConversion(converted)&&converted.Audio.Keys.All(k=>!System.Text.RegularExpressions.Regex.IsMatch(k,@"[a-f0-9]{32}")),"Converted audio IDs are readable stable names");
  return new{passed=true,checks,fixtures=root};
 }
}
